<script setup lang="ts">
import PmsHierarchyProjectNode from './PmsHierarchyProjectNode.vue';
import {ref,onMounted,onUnmounted} from 'vue';
import {pmsFetch,withoutPmsLoader} from './loading';
const workspaceOpened=ref(false);
const currentCompany=ref<number|null>(null);
const currentClient=ref<number|null>(null),currentProject=ref<number|null>(null),currentDepartment=ref<number|null>(null);function selection(){const q=new URLSearchParams(location.search);currentCompany.value=q.get('board-scope')==='company'?Number(q.get('board-id'))||null:null;currentClient.value=(q.get('board-scope')==='client'?Number(q.get('board-id')):Number(q.get('client')))||null;currentProject.value=(q.get('board-scope')==='project'?Number(q.get('board-id')):Number(q.get('project')))||null;currentDepartment.value=Number(q.get('department'))||null;if(currentCompany.value||currentClient.value||currentProject.value)workspaceOpened.value=true;}selection();
const emit=defineEmits(['client','project','board','preview']);const companies=ref<any[]>([]),legacy=ref<any[]>([]),error=ref('');
async function load(){try{const r=await withoutPmsLoader(()=>pmsFetch('/pms/api/hierarchy',{headers:{Accept:'application/json'}}));const d=await r.json();if(!r.ok)throw Error(d.message||'Unable to load workspace.');companies.value=d.companies;legacy.value=d.unassigned_projects;selection();}catch(e){error.value=(e as Error).message;}}
function companyToggle(event:Event){const company=event.currentTarget as HTMLDetailsElement;if(!company.open)return;const root=company.parentElement;root?.querySelectorAll<HTMLDetailsElement>(':scope > details.pms-tree-company').forEach(other=>{if(other!==company)other.open=false;});}
onMounted(()=>{void load();window.addEventListener('pms:hierarchy-changed',load);window.addEventListener('pms:navigation',selection);});onUnmounted(()=>{window.removeEventListener('pms:hierarchy-changed',load);window.removeEventListener('pms:navigation',selection);});
</script>
<template><div class="pms-hierarchy-nav"><details class="pms-client-workspace" :open="workspaceOpened" @toggle="workspaceOpened=($event.currentTarget as HTMLDetailsElement).open"><summary :class="{active:!!currentCompany||!!currentClient||!!currentProject}"><i class="ti ti-users" aria-hidden="true"></i><span class="pms-tree-label">Client Workspace</span><i class="ti ti-chevron-right pms-tree-chevron" aria-hidden="true"></i></summary><div class="pms-client-workspace-content"><p v-if="error" class="small text-danger">{{error}}</p><details v-for="company in companies" :key="company.id" class="pms-tree-company" name="pms-company-tree" @toggle="companyToggle" :open="company.id===currentCompany||company.clients.some((c:any)=>c.id===currentClient||c.projects.some((p:any)=>p.id===currentProject))||company.unassigned_projects.some((p:any)=>p.id===currentProject)"><summary><i aria-hidden="true" class="ti ti-building"></i><span class="pms-tree-label" :title="company.name">{{company.name}}</span><button class="pms-tree-eye" :aria-label="'View company board: '+company.name" :title="'View all '+company.name+' tasks'" @click.stop.prevent="emit('preview','company',company.id)"><i class="ti ti-eye" aria-hidden="true"></i></button><i class="ti ti-chevron-right pms-tree-chevron" aria-hidden="true"></i></summary><div class="pms-tree-children"><details v-for="client in company.clients" :key="client.id" class="pms-tree-node pms-hierarchy-client" :open="client.id===currentClient||client.projects.some((p:any)=>p.id===currentProject)"><summary><button class="pms-tree-label" :title="client.name" @click.stop="emit('client',client.id)">{{client.name}}</button><button class="pms-tree-eye" :aria-label="'View client board: '+client.name" :title="'View all '+client.name+' tasks'" @click.stop.prevent="emit('preview','client',client.id)"><i class="ti ti-eye" aria-hidden="true"></i></button><i class="ti ti-chevron-right pms-tree-chevron" aria-hidden="true"></i></summary><div class="pms-tree-children"><PmsHierarchyProjectNode v-for="project in client.projects" :key="project.id" :project="project" :current-project="currentProject" :current-department="currentDepartment" @project="emit('project',$event)" @board="(p,d)=>emit('board',p,d)" @preview="(s,id)=>emit('preview',s,id)"/></div></details><details v-if="company.unassigned_projects.length" class="pms-tree-node" :open="company.unassigned_projects.some((p:any)=>p.id===currentProject)"><summary><span class="pms-tree-label">Projects without a client</span><i class="ti ti-chevron-right pms-tree-chevron" aria-hidden="true"></i></summary><div class="pms-tree-children"><PmsHierarchyProjectNode v-for="project in company.unassigned_projects" :key="project.id" :project="project" :current-project="currentProject" :current-department="currentDepartment" @project="emit('project',$event)" @board="(p,d)=>emit('board',p,d)" @preview="(s,id)=>emit('preview',s,id)"/></div></details></div></details><details v-if="legacy.length" class="pms-tree-node"><summary><span class="pms-tree-label">Projects to organize</span><i class="ti ti-chevron-right pms-tree-chevron" aria-hidden="true"></i></summary><div class="pms-tree-children"><PmsHierarchyProjectNode v-for="project in legacy" :key="project.id" :project="project" :current-project="currentProject" :current-department="currentDepartment" @project="emit('project',$event)" @board="(p,d)=>emit('board',p,d)" @preview="(s,id)=>emit('preview',s,id)"/></div></details></div></details></div></template>
